// Obejscie new T():
static <T> T createInstance(Supplier<T> fabryka) {
    return fabryka.get(); // NIE 'new T()'
}
String s = createInstance(String::new);

// Obejscie new T[10]:
@SuppressWarnings("unchecked")
static <T> T[] createArraySafe(Class<T> typ, int rozmiar) {
    return (T[]) Array.newInstance(typ, rozmiar); // WLASCIWY typ w runtime
}
String[] arr = createArraySafe(String.class, 3);

